        title: '先旋轉再翻轉，跟先翻轉再旋轉，結果方向不一樣',
        text: '程式繪製順序固定是「先套用旋轉角度、再套用水平／垂直翻轉」，這代表操作順序雖然是你自己按的，但最後方向要用「旋轉後的座標系」來理解水平/垂直翻轉，而不是永遠對應原圖的左右或上下。實務上直接用眼睛核對預覽圖是否符合你要的方向最可靠，不要只憑腦中想像的旋轉加翻轉去推算。',
