      '已核對旋轉 90 度或 270 度後，「尺寸」欄位顯示的寬高確實對調。',
      '知道每次調整都是從原始圖重新計算，不是疊加壓縮，只有最終匯出的 JPEG 品質固定為 0.92。',
      '同時使用旋轉與翻轉時，已直接看預覽圖確認方向，而不是單憑心算操作順序判斷結果。',
